    [30894] = { en = "Increases your Stealth detection as if you were ${$m1/5} $llevel:levels; higher and reduces your chance to be hit by spells and ranged attacks by $m2%.", description = "Aumenta la capacità di individuare le unità furtive come se avessi ${$m1/5} $llivello:livelli; in più e riduce del $m2% la probabilità di essere colpito da incantesimi e attacchi a distanza." },
    [30902] = { en = "Increases your Attack Power by $s1%.", description = "Aumenta la tua potenza d’attacco del $s1%." },
    [30919] = { en = "Reduces the chance for your attacks to be Dodged or Parried by $m1%.", description = "Riduce del $m1% la probabilità che i tuoi attacchi vengano schivati o parati." },
    [31018] = { en = "Finishing move that causes damage per combo point and converts each extra point of energy into ${$m2/100}.1 additional damage.  Damage is increased by your Attack Power.\r\n   1 point  : 199-259 damage\r\n   2 points: 346-406 damage\r\n   3 points: 493-553 damage\r\n   4 points: 640-700 damage\r\n   5 points: 787-847 damage", description = "Mossa finale che infligge danni in base ai punti combo e converte ogni punto energia in eccesso in ${$m2/100}.1 danni aggiuntivi. I danni aumentano in base alla tua potenza d’attacco.\r\n   1 punto  : 199-259 danni\r\n   2 punti: 346-406 danni\r\n   3 punti: 493-553 danni\r\n   4 punti: 640-700 danni\r\n   5 punti: 787-847 danni" },
    [31255] = { en = "Increases your movement speed by 10% whenever you deal damage to a target who is below 20% health.", description = "Aumenta la tua velocità di movimento del 10% ogni volta che infliggi danni a un bersaglio con meno del 20% di salute." },
    [31364] = { en = "$s1 Fire damage to area enemies. ", description = "$s1 danni da fuoco ai nemici nell’area." },
    [31700] = { en = "Summons and dismisses a rideable Qiraji battle tank. This is a very fast mount.", description = "Evoca o congeda un carro armato da battaglia Qiraji cavalcabile. È una cavalcatura molto veloce." },
    [31750] = { en = "Increases damage and healing done by magical spells and effects by up to $s1.", description = "Aumenta fino a $s1 i danni e le cure inflitti dagli incantesimi e dagli effetti magici." },
    [32309] = { en = "Shoots poison at an enemy, inflicting Nature damage, then additional damage every $t2 sec. for $d.", description = "Scaglia veleno contro un nemico, infliggendo danni da natura e poi danni aggiuntivi ogni $t2 sec. per $d." },
    [33389] = { en = "Allows the player to ride basic ground mounts that require a riding skill of 75.", description = "Permette al giocatore di cavalcare le cavalcature terrestri di base che richiedono abilità di equitazione 75." },
    [33392] = { en = "Allows the player to ride swift ground mounts that require a riding skill of 150.", description = "Permette al giocatore di cavalcare le cavalcature terrestri veloci che richiedono abilità di equitazione 150." },
    [34074] = { en = "The hunter takes on the aspect of the viper, causing ranged and melee attacks to regenerate mana but reducing your total damage done by $34074s2%.  In addition, you gain $s1% of maximum mana every $t sec.  Mana gained is based on the speed of your ranged weapon. Requires a ranged weapon. Only one Aspect can be active at a time.", description = "Assumi l’aspetto della vipera: i tuoi attacchi a distanza e in mischia rigenerano mana, ma i danni totali inflitti sono ridotti del $34074s2%. Inoltre, ottieni il $s1% del mana massimo ogni $t sec. Il mana ottenuto dipende dalla velocità dell’arma a distanza. Richiede un’arma a distanza. Puoi avere un solo Aspetto attivo alla volta." },
    [34433] = { en = "Creates a shadowy fiend to attack the target.  Caster receives $34650s1% mana when the Shadowfiend attacks. Damage taken by area of effect attacks is reduced. Lasts $d.", description = "Evoca un demonietto d’ombra che attacca il bersaglio. Quando il demonietto colpisce, l’incantatore riceve il $34650s1% di mana. I danni subiti dagli attacchi ad area sono ridotti. Dura $d." },
    [42896] = { en = "Blasts the target with energy, dealing $s1 Arcane damage.  Each time you cast Arcane Blast, the damage of all Arcane spells is increased by $36032s1% and mana cost of Arcane Blast is increased by $36032s2%.  Effect stacks up to $36032u times and lasts $36032d or until any Arcane damage spell except Arcane Blast is cast.", description = "Colpisce il bersaglio con un’esplosione di energia, infliggendo $s1 danni arcani. Ogni lancio di Esplosione Arcana aumenta del $36032s1% i danni di tutti gli incantesimi arcani e aumenta del $36032s2% il costo in mana di Esplosione Arcana. L’effetto si accumula fino a $36032u volte e dura $36032d, oppure termina quando lanci un qualsiasi incantesimo che infligge danni arcani diverso da Esplosione Arcana." },
    [43308] = { en = "Nearby fishing nodes appear on the minimap.", description = "I banchi di pesca vicini appaiono sulla minimappa." },
    [43680] = { en = "Your teammates have reported you for laziness!  Enter PvP combat or you will be marked Inactive and unable to receive Honor Points.", description = "I tuoi compagni ti hanno segnalato per pigrizia! Partecipa al combattimento PvP o verrai contrassegnato come inattivo e non potrai ricevere punti onore." },
    [43681] = { en = "Cannot receive Honor Points until you enter PvP combat.\r\nYou will be kicked from the battleground if you remain Inactive.", description = "Non puoi ricevere punti onore finché non partecipi al combattimento PvP.\r\nVerrai espulso dal campo di battaglia se rimani inattivo." },
    [45440] = { en = "Summon and control your steam tonk.", description = "Evoca e controlla il tuo carro a vapore." },
    [48108] = { en = "Any time you score 2 spell criticals in a row using using Fireball, Fire Blast, Scorch, Living Bomb, or Frostfire Bolt, you have a chance the next Pyroblast spell cast within $d will be instant cast.", description = "Ogni volta che metti a segno 2 colpi critici consecutivi con Palla di Fuoco, Esplosione di Fuoco, Bruciatura, Bomba Vivente o Dardo di Fuocogelo, hai la possibilità di lanciare istantaneamente il successivo Incenerimento entro $d." },
    [53489] = { en = "Increases the critical strike damage of your Judgement, Crusader Strike and Divine Storm abilities by $53486s1% and when your melee attacks critically hit the cast time of your next Flash of Light or Exorcism is reduced by ${$53489m1/-1000}.2 sec.", description = "Aumenta del $53486s1% i danni critici delle abilità Giudizio, Attacco del Crociato e Tempesta Divina; inoltre, quando i tuoi attacchi in mischia mettono a segno un colpo critico, il tempo di lancio del tuo successivo Lampo di Luce o Esorcismo si riduce di ${$53489m1/-1000}.2 sec." },
    [53601] = { en = "Each time the target takes damage they gain a Sacred Shield, absorbing $58597s1 damage and increasing the paladin's chance to critically hit with Flash of Light by $58597s2% for up to $58597d.  They cannot gain this effect more than once every $s2 sec.  Lasts $d.  This spell cannot be on more than one target at any one time.", description = "Ogni volta che il bersaglio subisce danni, ottiene uno Scudo Sacro che assorbe $58597s1 danni e aumenta del $58597s2% la probabilità del paladino di mettere a segno colpi critici con Lampo di Luce per un massimo di $58597d. Non può ottenere questo effetto più di una volta ogni $s2 sec. Dura $d. Questo incantesimo può essere attivo su un solo bersaglio alla volta." },
    [53672] = { en = "Your Holy Shock critical hits reduce the cast time of your next Flash of Light by ${$53672m2/-1000}.2 sec or increase the critical chance of your next Holy Light by $s1%.", description = "I colpi critici di Shock Sacro riducono di ${$53672m2/-1000}.2 sec. il tempo di lancio del tuo successivo Lampo di Luce oppure aumentano del $s1% la probabilità di colpo critico del tuo successivo Luce Sacra." },
    [58597] = { en = "Each time the target takes damage they gain a Sacred Shield, absorbing $58597s1 damage and increasing the paladin's chance to critically hit with Flash of Light by $58597s2% for up to $58597d.  They cannot gain this effect more than once every 6 sec.  Lasts $d.", description = "Ogni volta che il bersaglio subisce danni, ottiene uno Scudo Sacro che assorbe $58597s1 danni e aumenta del $58597s2% la probabilità del paladino di mettere a segno colpi critici con Lampo di Luce per un massimo di $58597d. Non può ottenere questo effetto più di una volta ogni 6 sec. Dura $d." },
    [63624] = { en = "Learn a Second Talent Specialization.", description = "Apprendi una seconda specializzazione dei talenti." },
    [63644] = { en = "Switch to your Secondary Talent Specialization.", description = "Passa alla specializzazione secondaria dei talenti." },
    [63645] = { en = "Switch to your Primary Talent Specialization.", description = "Passa alla specializzazione primaria dei talenti." },
    [64659] = { en = "Summons and dismisses a rideable Venomhide Ravasaur.", description = "Evoca o congeda un Ravasauro Velenopelle cavalcabile." },
    [65183] = { en = "Summons your Venomhide Hatchling. May only be used in Un'Goro Crater, Tanaris, or Silithus.", description = "Evoca il tuo cucciolo di Velenopelle. Può essere usato solo nel Cratere di Un’Goro, a Tanaris o a Silitus." },
    [77746] = { en = "Causes your Fire totems to increase the spell power of party and raid members within $77747a1 yards by $s1%.", description = "I tuoi totem di fuoco aumentano la potenza magica dei membri del gruppo e dell'incursione entro $77747a1 m del $s1%." },
    [77747] = { en = "Causes your Fire totems to increase the spell power of party and raid members within $a1 yards by $s1% .", description = "I tuoi totem di fuoco aumentano la potenza magica dei membri del gruppo e dell'incursione entro $a1 m del $s1%." },
    [78156] = { en = "Summons a Tremor Totem with $s1 health at the feet of the caster that shakes the ground around it, removing Fear, Charm and Sleep effects from party members within $8146a1 yards.  Lasts $d.", description = "Evoca ai piedi dell’incantatore un Totem del Tremore con $s1 salute. Il totem scuote il terreno circostante e rimuove gli effetti di Paura, Ammaliamento e Sonno dai membri del gruppo entro $8146a1 m. Dura $d." },
    [78159] = { en = "Summons a Windfury Totem with $s1 health at the feet of the caster.  The totem provides $8515s1% melee haste to all party and raid members within $8515a1 yards.  Lasts $d.", description = "Evoca ai piedi dell’incantatore un Totem della Furia del Vento con $s1 salute. Il totem fornisce il $8515s1% di celerità in mischia a tutti i membri del gruppo e dell’incursione entro $8515a1 m. Dura $d." },
    [79429] = { en = "Summons an Elemental Resistance totem.", description = "Evoca un totem di resistenza agli elementi." },
    [79431] = { en = "Summons an Elemental Resistance totem.", description = "Evoca un totem di resistenza agli elementi." },
}

ns.data.spellDescriptionOverrides = ns.data.spellDescriptionOverrides or {}
for id, description in pairs(verifiedSpellDescriptions) do
    ns.data.spellDescriptionOverrides[id] = description
    local entry = ns.data.spells[id]
    if type(entry) == "table" then
        entry.enDescription = description.en
        entry.description = description.description
    end
end
